import{_ as a,o as t,c as o,a2 as i}from"./chunks/framework.CHeM0PsO.js";const p=JSON.parse('{"title":"Lesson 11: Automation Tasks — Let Codex Run Errands for You","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/module-3/lesson-11.md","filePath":"en/modules/module-3/lesson-11.md"}'),s={name:"en/modules/module-3/lesson-11.md"};function n(r,e,l,d,c,h){return t(),o("div",null,[...e[0]||(e[0]=[i(`<h1 id="lesson-11-automation-tasks-—-let-codex-run-errands-for-you" tabindex="-1">Lesson 11: Automation Tasks — Let Codex Run Errands for You <a class="header-anchor" href="#lesson-11-automation-tasks-—-let-codex-run-errands-for-you" aria-label="Permalink to &quot;Lesson 11: Automation Tasks — Let Codex Run Errands for You&quot;">​</a></h1><blockquote><p>📌 <strong>Learning Objectives</strong>: Learn to use Codex to execute repetitive tasks, understand the difference between &quot;one-time tasks&quot; and &quot;reusable workflows&quot; ⏱️ <strong>Estimated Time</strong>: 25 minutes 🎯 <strong>Teaching Rhythm</strong>: Demo first → Explain → Practice</p></blockquote><hr><h2 id="i-what-are-automation-tasks" tabindex="-1">I. What Are &quot;Automation Tasks&quot;? <a class="header-anchor" href="#i-what-are-automation-tasks" aria-label="Permalink to &quot;I. What Are &quot;Automation Tasks&quot;?&quot;">​</a></h2><p>Automation Tasks mean: <strong>You tell Codex what to do, and it completes the entire process step by step, without you needing to repeatedly operate.</strong></p><h3 id="real-life-analogy" tabindex="-1">Real-Life Analogy <a class="header-anchor" href="#real-life-analogy" aria-label="Permalink to &quot;Real-Life Analogy&quot;">​</a></h3><p>Imagine you&#39;re moving house:</p><ul><li><strong>Manual way</strong>: You pack everything yourself, label each box, and carry it to the truck</li><li><strong>Automation way</strong>: You tell an assistant &quot;I&#39;m moving, take these things to the new place,&quot; and the assistant handles packing, labeling, and transporting on its own</li></ul><p>Codex is that &quot;assistant.&quot;</p><hr><h2 id="ii-practice-1-batch-rename-a-set-of-files" tabindex="-1">II. Practice 1: Batch Rename a Set of Files <a class="header-anchor" href="#ii-practice-1-batch-rename-a-set-of-files" aria-label="Permalink to &quot;II. Practice 1: Batch Rename a Set of Files&quot;">​</a></h2><h3 id="scenario" tabindex="-1">Scenario <a class="header-anchor" href="#scenario" aria-label="Permalink to &quot;Scenario&quot;">​</a></h3><p>You downloaded 50 photos, and the filenames are all <code>download_001.jpg</code>, <code>download_002.jpg</code>... You want to give them more meaningful names.</p><h3 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to &quot;Steps&quot;">​</a></h3><ol><li>Open the photos folder as the workspace</li><li>Type this command:<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Help me rename these photos by date, in the format &quot;ShootingDate_Sequence.jpg&quot;.</span></span>
<span class="line"><span>Example: 2026-07-20_001.jpg</span></span></code></pre></div></li><li>Codex will read each photo&#39;s EXIF data (if available) and batch-rename them.</li></ol><h3 id="more-batch-operation-examples" tabindex="-1">More Batch Operation Examples <a class="header-anchor" href="#more-batch-operation-examples" aria-label="Permalink to &quot;More Batch Operation Examples&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Your Need</th><th>Command Example</th></tr></thead><tbody><tr><td>Unify extension case</td><td>&quot;Change all .JPG to .jpg&quot;</td></tr><tr><td>Add a prefix/suffix</td><td>&quot;Add &#39;ProjectA-&#39; to the front of all filenames&quot;</td></tr><tr><td>Remove specific characters</td><td>&quot;Remove all spaces and underscores from filenames&quot;</td></tr><tr><td>Rename by rule</td><td>&quot;Change &#39;IMG_<em>.jpg&#39; to &#39;Trip_</em>.jpg&#39;&quot;</td></tr></tbody></table><hr><h2 id="iii-practice-2-automatically-download-and-organize-materials" tabindex="-1">III. Practice 2: Automatically Download and Organize Materials <a class="header-anchor" href="#iii-practice-2-automatically-download-and-organize-materials" aria-label="Permalink to &quot;III. Practice 2: Automatically Download and Organize Materials&quot;">​</a></h2><h3 id="scenario-1" tabindex="-1">Scenario <a class="header-anchor" href="#scenario-1" aria-label="Permalink to &quot;Scenario&quot;">​</a></h3><p>You need to collect online materials on a certain topic, but you don&#39;t want to click each link and copy-paste manually.</p><h3 id="steps-1" tabindex="-1">Steps <a class="header-anchor" href="#steps-1" aria-label="Permalink to &quot;Steps&quot;">​</a></h3><ol><li>In Codex, type:<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Help me search for the latest articles on &quot;remote work best practices&quot;, find the top 5 results, and organize each result&#39;s title, summary, and link into a document.</span></span></code></pre></div></li><li>Codex will: <ul><li>Search the web for relevant information</li><li>Extract the top 5 results</li><li>Create a Markdown file with the organized content</li></ul></li><li>You can then ask:<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Translate this document into Chinese.</span></span></code></pre></div>or<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Based on these materials, write a recommendation list about remote work.</span></span></code></pre></div></li></ol><hr><h2 id="iv-understand-one-time-task-vs-reusable-automation-workflow" tabindex="-1">IV. Understand &quot;One-Time Task&quot; vs &quot;Reusable Automation Workflow&quot; <a class="header-anchor" href="#iv-understand-one-time-task-vs-reusable-automation-workflow" aria-label="Permalink to &quot;IV. Understand &quot;One-Time Task&quot; vs &quot;Reusable Automation Workflow&quot;&quot;">​</a></h2><h3 id="one-time-task" tabindex="-1">One-Time Task <a class="header-anchor" href="#one-time-task" aria-label="Permalink to &quot;One-Time Task&quot;">​</a></h3><p>For example: &quot;Help me merge the PDF files in this folder into one.&quot;</p><ul><li>Do it once and it&#39;s done</li><li>If you need to do the same thing again, you have to tell Codex again</li></ul><h3 id="reusable-workflow" tabindex="-1">Reusable Workflow <a class="header-anchor" href="#reusable-workflow" aria-label="Permalink to &quot;Reusable Workflow&quot;">​</a></h3><p>For example: &quot;Every time a new email arrives, automatically extract the table data from the attachment and save it to Excel.&quot;</p><ul><li>Can be set to run periodically</li><li>Or made into a script/template for随时调用</li></ul><blockquote><p>💡 <strong>Tip</strong>: Codex can not only do one-time tasks but also help you write reusable scripts. When you find a task that you do often, ask Codex to turn it into an automation script.</p></blockquote><hr><h2 id="v-practice-3-create-your-first-automation-script" tabindex="-1">V. Practice 3: Create Your First Automation Script <a class="header-anchor" href="#v-practice-3-create-your-first-automation-script" aria-label="Permalink to &quot;V. Practice 3: Create Your First Automation Script&quot;">​</a></h2><h3 id="task" tabindex="-1">Task <a class="header-anchor" href="#task" aria-label="Permalink to &quot;Task&quot;">​</a></h3><p>Ask Codex to write an auto-generation script for your &quot;daily work report.&quot;</p><h3 id="steps-2" tabindex="-1">Steps <a class="header-anchor" href="#steps-2" aria-label="Permalink to &quot;Steps&quot;">​</a></h3><ol><li>Prepare a folder containing daily work records.</li><li>Type this command:<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Help me write a Python script that reads all log files in this folder,</span></span>
<span class="line"><span>counts the number of work entries per day, and generates a summary report.</span></span></code></pre></div></li><li>Codex will generate a reusable script.</li><li>Every morning, run the script once, and you&#39;ll automatically get the previous day&#39;s work summary.</li></ol><hr><h2 id="vi-in-lesson-practice-checklist" tabindex="-1">VI. In-Lesson Practice Checklist <a class="header-anchor" href="#vi-in-lesson-practice-checklist" aria-label="Permalink to &quot;VI. In-Lesson Practice Checklist&quot;">​</a></h2><p>Complete the following tasks in order:</p><ul><li>[ ] Have Codex batch-rename a set of files</li><li>[ ] Have Codex search the web for materials and organize them into a document</li><li>[ ] Try having Codex write a simple automation script</li><li>[ ] Reflect: What repetitive tasks in your work could you hand over to Codex for automation?</li></ul><hr><h2 id="vii-summary" tabindex="-1">VII. Summary <a class="header-anchor" href="#vii-summary" aria-label="Permalink to &quot;VII. Summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Knowledge Point</th><th>Core Content</th></tr></thead><tbody><tr><td>Automation Tasks</td><td>Let Codex handle repetitive work for you</td></tr><tr><td>Batch operations</td><td>Rename, move, classify, format, etc.</td></tr><tr><td>Web Search</td><td>Search + organize + summarize</td></tr><tr><td>One-time vs reusable</td><td>Simple tasks: just ask. Complex tasks: write a script</td></tr></tbody></table><hr><h2 id="viii-next-step" tabindex="-1">VIII. Next Step <a class="header-anchor" href="#viii-next-step" aria-label="Permalink to &quot;VIII. Next Step&quot;">​</a></h2><p><a href="./../module-4/lesson-12.html">→ Enter Module 4: Practical Tips</a></p>`,48)])])}const m=a(s,[["render",n]]);export{p as __pageData,m as default};
